import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'docs/artifacts/v9_completed_9412383_2026-11-02';BASE='../artifacts/'+OUT.name+'/'
def build(table):
 meta=json.loads((OUT/'checkpoints.json').read_text());history=json.loads((OUT/'history.json').read_text());summary=json.loads((OUT/'summary.json').read_text());movies=json.loads((OUT/'videos.json').read_text())
 result='''<section id="e19" class="stage"><div class="stage-label">Etap 19 · v9 zakończony · 02.11.2026</div><h2>V9: granica 4 m/s na wszystkich badanych wysokościach</h2><p class="lead">V9 zakończył 30 015 488 dodatkowych przejść po v8. Oba końcowe checkpointy przekraczają 80% na kolejnych punktach siatki do 4 m/s dla wysokości 1–3 m. Best i latest mają różne wagi oraz lokalne mocne i słabe punkty.</p><p>Best zapisano przy 25 165 824 nowych przejściach, latest przy 30 015 488. Razem z v8 oznacza to odpowiednio 55 181 312 i 60 030 976 przejść łańcucha uczenia, a nie trening v9 od nowych wag. Fizykę, PD, nagrody i pomiar prędkości zachowano. Warunki początkowe nadal mają zerowy przechył.</p>'''
 result+=table(['Model','Nowe przejścia','Średnia v>0','Najgorsza średnia wysokości w paśmie 3–4 m/s','Nominalnie'],[[n,str(meta[n]['metrics']['nr_env_steps']),f"{100*meta[n]['metrics']['eval/landing_success_rate']:.2f}%",f"{100*meta[n]['metrics']['eval/worst_height_success_rate']:.2f}%",f"{100*meta[n]['metrics']['eval/nominal/policy/success_rate']:.1f}%"] for n in ['best','latest']])
 result+='''<p>Średnie v9 są liczone na gęstszej siatce niż v8, a kryterium best obejmuje pasmo 3–4 m/s. Nie porównujemy wprost tych średnich z dawną średnią v8. Best jest wybrany według najgorszej średniej wysokości, więc nie musi wygrywać z latest w każdej komórce. W logu brak Traceback, OOM i NaN. Nie pobrano oryginalnych CSV ewaluacji z klastra: siatki best/latest odczytano dokładnie z checkpointów, pośrednie z drukowanego logu.</p><h3>Końcowe wyniki przy 4 i 5 m/s</h3>'''
 lookup={n:{(c['height'],c['speed']):c for c in history['checkpoint_grids'][n]['cells'] if c['controller']=='policy'} for n in ['best','latest']}
 result+=table(['Wysokość','Best 4 m/s','Latest 4 m/s','Best 5 m/s','Latest 5 m/s'],[[f'{h:g} m']+[f"{lookup[n][h,v]['successes']}/64 ({100*lookup[n][h,v]['success_rate']:.1f}%)" for v,n in [(4,'best'),(4,'latest'),(5,'best'),(5,'latest')]] for h in [1.,1.5,2.,2.5,3.]])
 result+='<figure class="chart"><img src="'+BASE+'grids.png" alt="Pełne siatki best/latest v9"><figcaption>64 epizody na komórkę, dokładny moduł prędkości; 5 m/s pozostaje punktem diagnostycznym i nie przekracza 80% na żadnej wysokości.</figcaption></figure>'
 result+='<h3>Porównanie z v8 na identycznych przypadkach</h3>'
 result+=table(['Warunki','Model','Sukcesy','Skuteczność','95% Wilson'],[[f"{g['height']:g} m / {g['speed']:g} m/s",g['controller'],f"{g['successes']}/{g['count']}",f"{100*g['rate']:.1f}%",f"{100*g['wilson95'][0]:.1f}–{100*g['wilson95'][1]:.1f}%"] for g in summary['groups']])
 result+='''<p>Wykonano 384 nowe epizody (po 192 dla best i latest), korzystając z zamrożonych przypadków poprzedniej diagnozy v8. Sprawdzono hashe fizycznych stanów początkowych względem v8. Są to próby sparowane, ale nie nowy niewidziany zbiór dla v9: te przypadki służyły do diagnozy i zaplanowania treningu. Przy 3 m / 4 m/s v8 miał 53/64 sukcesów, v9 best ma 62/64, a latest 64/64. Oba checkpointy naprawiły wszystkie 11 dawnych porażek; best wprowadził dwie nowe porażki w innych przypadkach, latest nie stracił żadnego dawnego sukcesu. Przy 2,5 m / 4 m/s oba osiągnęły 64/64 wobec 59/64 v8. Przy 3 m / 5 m/s best osiągnął 14/64, latest 21/64 wobec 17/64 v8 — nadal daleko od 80%. Do niezależnego wniosku artykułu potrzebne są nowe seedy ewaluacji i kolejne seedy uczenia.</p>'''
 result+=table(['Warunki','Porównanie A → B','Sukces tylko A','Sukces tylko B'],[[f"{p['height']:g} m / {p['speed']:g} m/s",p['a']+' → '+p['b'],str(p['a_only']),str(p['b_only'])] for p in summary['paired']])
 result+='<figure class="chart"><img src="'+BASE+'paired.png" alt="Porównanie v8 i obu checkpointów v9 na tych samych przypadkach"></figure><h3>Film: skrajna potwierdzona komórka 3 m / 4 m/s</h3>'
 movie=movies[0]
 result+=f'<figure><video controls preload="metadata" src="{movie["src"]}" poster="{movie["poster"]}"></video><figcaption>Best i latest, identyczny stan początkowy i szum sensora. Pierwszy przypadek wspólnego sukcesu w zamrożonym zestawie; dobór retrospektywny, film jest ilustracją. Wyniki i czasy końca sprawdzono osobnymi replayami. 4× wolniej, obraz zatrzymuje się po wyniku.</figcaption></figure>'
 result+='<h3>Rozwój granicy >80% w v9</h3>'
 result+=table(['Nowe przejścia','1 m','1,5 m','2 m','2,5 m','3 m'],[[str(e['step'])]+[str(e['contiguous_speed_boundary'][f'{h:g}'])+' m/s' for h in [1.,1.5,2.,2.5,3.]] for e in history['evaluations']])
 result+='''<p>Granica do 4 m/s jest obecna już przy pierwszej zapisanej ewaluacji v9 (8 388 608 nowych przejść). Nie znamy wcześniejszej chwili przekroczenia, bo nie wykonywano pomiaru pomiędzy ewaluacjami. To granica kolejnych punktów siatki, nie gwarancja dla wszystkich kierunków i warunków pośrednich.</p><h3>Wnioski i ograniczenia</h3><p>Kontynuacja v8 z koncentracją na 3–4 m/s rozszerzyła potwierdzony w walidacji zakres do 4 m/s także przy niższych wysokościach. Brak podstaw do uznania 5 m/s za opanowane. Różnica best/latest pokazuje potrzebę wyboru checkpointu względem całego wymaganego zakresu, a nie tylko 3 m. Nie przypisujemy poprawy samemu rozkładowi: v9 otrzymał dodatkowy budżet uczenia. Nowe strategie po kontakcie wymagają osobnej definicji zadania i osobnego eksperymentu; wyniki v9 nadal oceniają uspokojenie po lądowaniu według dotychczasowych kryteriów.</p>'''
 result+=f'<p><a href="{BASE}checkpoints.json">Metryki i hashe modeli</a> · <a href="{BASE}history.json">Historia siatek</a> · <a href="{BASE}paired_results.json">Pełne odtworzenia</a> · <a href="{BASE}summary.json">Porównania i przedziały ufności</a></p></section>'
 return result

def overview():
 return '<section id="aktualnie" class="stage"><div class="stage-label">Aktualny stan · 02.11.2026</div><h2>V9 zakończony: granica do 4 m/s na wysokościach 1–3 m</h2><p>Best i latest różnią się wagami. Oba przekraczają 80% w kolejnych komórkach walidacji do 4 m/s, bez początkowych przechyłów. Przeprowadzono porównanie sparowane z v8 i przygotowano film 3 m / 4 m/s.</p><p><a href="#e19">Wyniki v9 i film</a> · <a href="#branch-aerial">Równoległy tor: obrót w powietrzu</a></p></section>'
